-- EduNova v0.24.0 LOT 23 — Teaching & Course Delivery.
CREATE TABLE teaching_courses(id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL REFERENCES campus_institutions(id) ON DELETE RESTRICT,code varchar(64) NOT NULL,title varchar(240) NOT NULL,description varchar(4000) NOT NULL DEFAULT '',credits integer,state varchar(24) NOT NULL CHECK(state IN ('draft','published','archived')),row_version integer NOT NULL,created_by varchar(64) NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,UNIQUE(institution_id,code));
CREATE TABLE teaching_offerings(id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL REFERENCES campus_institutions(id) ON DELETE RESTRICT,course_id varchar(64) NOT NULL REFERENCES teaching_courses(id) ON DELETE RESTRICT,cohort_id varchar(64) NOT NULL REFERENCES campus_cohorts(id) ON DELETE RESTRICT,academic_period_id varchar(64) NOT NULL REFERENCES campus_academic_periods(id) ON DELETE RESTRICT,label varchar(240) NOT NULL,state varchar(24) NOT NULL CHECK(state IN ('draft','published','archived')),row_version integer NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE TABLE teaching_teacher_assignments(id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL REFERENCES campus_institutions(id) ON DELETE RESTRICT,offering_id varchar(64) NOT NULL REFERENCES teaching_offerings(id) ON DELETE RESTRICT,teacher_account_id varchar(64) NOT NULL,role varchar(24) NOT NULL CHECK(role IN ('lead','co_teacher','assistant')),active boolean NOT NULL,created_at timestamptz NOT NULL,UNIQUE(offering_id,teacher_account_id));
CREATE TABLE teaching_sessions(id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL REFERENCES campus_institutions(id) ON DELETE RESTRICT,offering_id varchar(64) NOT NULL REFERENCES teaching_offerings(id) ON DELETE RESTRICT,title varchar(240) NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,state varchar(24) NOT NULL CHECK(state IN ('planned','completed','cancelled')),summary varchar(8000) NOT NULL DEFAULT '',next_topic varchar(2000) NOT NULL DEFAULT '',row_version integer NOT NULL,created_by varchar(64) NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,CHECK(ends_at>starts_at));
CREATE TABLE teaching_resources(id varchar(64) PRIMARY KEY,institution_id varchar(64) NOT NULL REFERENCES campus_institutions(id) ON DELETE RESTRICT,offering_id varchar(64) NOT NULL REFERENCES teaching_offerings(id) ON DELETE RESTRICT,title varchar(240) NOT NULL,resource_type varchar(48) NOT NULL,uri varchar(1500) NOT NULL,source_revision varchar(128),state varchar(24) NOT NULL CHECK(state IN ('draft','published','retired')),row_version integer NOT NULL,created_by varchar(64) NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE INDEX ix_teaching_offering_scope ON teaching_offerings(institution_id,cohort_id,academic_period_id,state);
CREATE INDEX ix_teaching_teacher_workload ON teaching_teacher_assignments(institution_id,teacher_account_id,active);
CREATE INDEX ix_teaching_session_timeline ON teaching_sessions(institution_id,offering_id,starts_at,state);
CREATE INDEX ix_teaching_resource_catalog ON teaching_resources(institution_id,offering_id,state);
